using Microsoft.AspNetCore.Components;
using sv_5d0933907ec744eca98d8f97d5f9c2f7.Models;
using sv_5d0933907ec744eca98d8f97d5f9c2f7.Services;

namespace sv_5d0933907ec744eca98d8f97d5f9c2f7.Components.Pages;

public partial class Settings : ComponentBase
{
    private string activeSection = "Profile";
    private bool isLoading = true;

    // Toast
    private string toastMessage = "";
    private string toastType = "";
    private CancellationTokenSource? toastCts;

    // Profile state
    private UserProfile? savedProfile;
    private string editDisplayName = "";
    private string editEmail = "";
    private string editAvatarUrl = "";
    private string editBio = "";

    // Notifications state
    private NotificationPrefs? savedNotificationPrefs;
    private bool editEmailNotifications;
    private bool editPushNotifications;
    private bool editWeeklyDigest;
    private List<string> editMutedChannels = new();
    private readonly List<string> availableChannels = new()
    {
        "general", "announcements", "random", "engineering", "design", "marketing"
    };

    // Security state
    private SecuritySettings? securitySettings;
    private bool showPasswordPanel;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string passwordError = "";
    private bool showRevokeConfirmation;
    private string? sessionToRevoke;

    // Appearance state
    private AppearanceSettings? savedAppearance;
    private string editTheme = "Light";
    private string editFontSize = "Medium";
    private string editLanguage = "en";
    private bool editCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData();
    }

    private async Task SetSection(string section)
    {
        if (activeSection == section) return;
        activeSection = section;
        isLoading = true;
        await LoadSectionData();
    }

    private async Task LoadSectionData()
    {
        try
        {
            switch (activeSection)
            {
                case "Profile":
                    savedProfile = await SettingsService.GetProfileAsync();
                    LoadProfileEdit();
                    break;
                case "Notifications":
                    savedNotificationPrefs = await SettingsService.GetNotificationPrefsAsync();
                    LoadNotificationEdit();
                    break;
                case "Security":
                    securitySettings = await SettingsService.GetSecuritySettingsAsync();
                    ResetPasswordFields();
                    break;
                case "Appearance":
                    savedAppearance = await SettingsService.GetAppearanceAsync();
                    LoadAppearanceEdit();
                    break;
            }
        }
        finally
        {
            isLoading = false;
        }
    }

    // Profile methods
    private void LoadProfileEdit()
    {
        if (savedProfile == null) return;
        editDisplayName = savedProfile.DisplayName;
        editEmail = savedProfile.Email;
        editAvatarUrl = savedProfile.AvatarUrl;
        editBio = savedProfile.Bio;
    }

    private async Task SaveProfile()
    {
        var updated = new UserProfile(editDisplayName, editEmail, editAvatarUrl, editBio);
        await SettingsService.SaveProfileAsync(updated);
        savedProfile = updated;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        LoadProfileEdit();
    }

    // Notifications methods
    private void LoadNotificationEdit()
    {
        if (savedNotificationPrefs == null) return;
        editEmailNotifications = savedNotificationPrefs.EmailNotifications;
        editPushNotifications = savedNotificationPrefs.PushNotifications;
        editWeeklyDigest = savedNotificationPrefs.WeeklyDigest;
        editMutedChannels = new List<string>(savedNotificationPrefs.MutedChannels);
    }

    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted && !editMutedChannels.Contains(channel))
            editMutedChannels.Add(channel);
        else if (!isMuted)
            editMutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var updated = new NotificationPrefs(editEmailNotifications, editPushNotifications, editWeeklyDigest, new List<string>(editMutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(updated);
        savedNotificationPrefs = updated;
        ShowToast("Notification preferences saved!", "success");
    }

    // Security methods
    private void TogglePasswordPanel()
    {
        showPasswordPanel = !showPasswordPanel;
        if (!showPasswordPanel) ResetPasswordFields();
    }

    private void ResetPasswordFields()
    {
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        passwordError = "";
    }

    private async Task UpdatePassword()
    {
        passwordError = "";

        if (string.IsNullOrWhiteSpace(currentPassword))
        {
            passwordError = "Current password is required.";
            return;
        }

        if (string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "New password is required.";
            return;
        }

        if (newPassword != confirmPassword)
        {
            passwordError = "Passwords do not match.";
            return;
        }

        if (newPassword.Length < 8)
        {
            passwordError = "Password must be at least 8 characters.";
            return;
        }

        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            ResetPasswordFields();
            showPasswordPanel = false;
            ShowToast("Password updated successfully!", "success");
        }
        catch (Exception ex)
        {
            passwordError = ex.Message;
        }
    }

    private void RequestRevoke(string sessionId)
    {
        sessionToRevoke = sessionId;
        showRevokeConfirmation = true;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
        showRevokeConfirmation = false;
    }

    private async Task ConfirmRevoke()
    {
        if (sessionToRevoke == null) return;

        await SettingsService.RevokeSessionAsync(sessionToRevoke);
        showRevokeConfirmation = false;
        sessionToRevoke = null;

        // Reload security settings
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
        ShowToast("Session revoked.", "success");
    }

    // Appearance methods
    private void LoadAppearanceEdit()
    {
        if (savedAppearance == null) return;
        editTheme = savedAppearance.Theme;
        editFontSize = savedAppearance.FontSize;
        editLanguage = savedAppearance.Language;
        editCompactMode = savedAppearance.CompactMode;
    }

    private async Task SaveAppearance()
    {
        var updated = new AppearanceSettings(editTheme, editFontSize, editLanguage, editCompactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        savedAppearance = updated;
        ShowToast("Appearance settings saved!", "success");
    }

    private string GetLanguageName(string code) => code switch
    {
        "en" => "English",
        "es" => "Spanish",
        "fr" => "French",
        "de" => "German",
        "ja" => "Japanese",
        "zh" => "Chinese",
        "pt" => "Portuguese",
        _ => code
    };

    // Toast helpers
    private async void ShowToast(string message, string type)
    {
        toastCts?.Cancel();
        toastCts = new CancellationTokenSource();
        var token = toastCts.Token;

        toastMessage = message;
        toastType = type;
        StateHasChanged();

        try
        {
            await Task.Delay(4000, token);
            DismissToast();
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    private void DismissToast()
    {
        toastMessage = "";
        toastType = "";
    }
}

