    private bool isLoading = true;

    // Toast
    private string toastMessage = "";
    private string toastType = "";
    private CancellationTokenSource? toastCts;

    // Profile state
    private UserProfile? savedProfile;
    private string editDisplayName = "";
    private string editEmail = "";
    private string editAvatarUrl = "";
    private string editBio = "";

    // Notifications state
    private NotificationPrefs? savedNotificationPrefs;
    private bool editEmailNotifications;
    private bool editPushNotifications;
    private bool editWeeklyDigest;
    private List<string> editMutedChannels = new();
    private readonly List<string> availableChannels = new()
    {
        "general", "announcements", "random", "engineering", "design", "marketing"
    };

    // Security state
    private SecuritySettings? securitySettings;
    private bool showPasswordPanel;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string passwordError = "";
    private bool showRevokeConfirmation;
    private string? sessionToRevoke;

    // Appearance state
    private AppearanceSettings? savedAppearance;
    private string editTheme = "Light";
    private string editFontSize = "Medium";
    private string editLanguage = "en";
    private bool editCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData();
    }

    private async Task SetSection(string section)
    {
        if (activeSection == section) return;
        activeSection = section;
        isLoading = true;
        await LoadSectionData();
    }

    private async Task LoadSectionData()
    {
        try
        {
            switch (activeSection)
            {
                case "Profile":
                    savedProfile = await SettingsService.GetProfileAsync();
                    LoadProfileEdit();
                    break;
                case "Notifications":
                    savedNotificationPrefs = await SettingsService.GetNotificationPrefsAsync();
                    LoadNotificationEdit();
                    break;
                case "Security":
                    securitySettings = await SettingsService.GetSecuritySettingsAsync();
                    ResetPasswordFields();
                    break;
                case "Appearance":
                    savedAppearance = await SettingsService.GetAppearanceAsync();
                    LoadAppearanceEdit();
                    break;
            }
        }
        finally
        {
            isLoading = false;
        }
    }

    // Profile methods
    private void LoadProfileEdit()
    {
        if (savedProfile == null) return;
        editDisplayName = savedProfile.DisplayName;
        editEmail = savedProfile.Email;
        editAvatarUrl = savedProfile.AvatarUrl;
        editBio = savedProfile.Bio;
    }

    private async Task SaveProfile()
    {
        var updated = new UserProfile(editDisplayName, editEmail, editAvatarUrl, editBio);
        await SettingsService.SaveProfileAsync(updated);
        savedProfile = updated;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        LoadProfileEdit();
    }

    // Notifications methods
    private void LoadNotificationEdit()
    {
        if (savedNotificationPrefs == null) return;
        editEmailNotifications = savedNotificationPrefs.EmailNotifications;
        editPushNotifications = savedNotificationPrefs.PushNotifications;
        editWeeklyDigest = savedNotificationPrefs.WeeklyDigest;
        editMutedChannels = new List<string>(savedNotificationPrefs.MutedChannels);
    }

    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted && !editMutedChannels.Contains(channel))
            editMutedChannels.Add(channel);
        else if (!isMuted)
            editMutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var updated = new NotificationPrefs(editEmailNotifications, editPushNotifications, editWeeklyDigest, new List<string>(editMutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(updated);
        savedNotificationPrefs = updated;
        ShowToast("Notification preferences saved!", "success");
    }

