        "fr" => "French",
        "de" => "German",
        "ja" => "Japanese",
        "zh" => "Chinese",
        "pt" => "Portuguese",
        _ => code
    };

    // Toast helpers
    private async void ShowToast(string message, string type)
    {
        toastCts?.Cancel();
        toastCts = new CancellationTokenSource();
        var token = toastCts.Token;

        toastMessage = message;
        toastType = type;
        StateHasChanged();

        try
        {
            await Task.Delay(4000, token);
            DismissToast();
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    private void DismissToast()
    {
        toastMessage = "";
        toastType = "";
    }
}

